+authors = ["David Tolnay <dtolnay@gmail.com>"]
+build = false
+exclude = ["build.rs"]
+autolib = false
+autobins = false
+autoexamples = false
+autotests = false
+autobenches = false
+description = "Parser and evaluator for Cargo's flavor of Semantic Versioning"
